const stages=[{name:'빛이 잠든 동굴',depth:'−1,200 M',color:0x34556c,fog:.034,note:'박에울: “올페야… 앞장서. 천천히 따라갈게.”',points:[[6,15],[6,12],[3,12],[3,8],[8,8],[8,4],[6,4],[6,1]]},{name:'잊힌 등반로',depth:'−860 M',color:0x477187,fog:.027,note:'김올페: “누군가 남긴 사다리야. 위로 이어져 있어.”',points:[[6,15],[6,13],[9,13],[9,9],[4,9],[4,5],[6,5],[6,1]]},{name:'깨진 빙하의 방',depth:'−520 M',color:0x6c9bab,fog:.024,note:'박에울: “얼음 사이가 벌어져 있어. 먼저 뛰면 나도 뛸게.”',points:[[6,15],[6,10],[3,10],[3,6],[8,6],[8,3],[6,3],[6,1]]},{name:'눈 속의 쉼터',depth:'−180 M',color:0x9bc3d0,fog:.018,note:'김올페: “바람이 느껴져. 이제 바깥이 가까워.”',points:[[6,15],[6,12],[9,12],[9,7],[4,7],[4,4],[6,4],[6,1]]},{name:'빛이 닿는 꼭대기',depth:'+240 M',color:0xc3e7ef,fog:.012,note:'박에울: “저 빛… 보여. 마지막까지 같이 가자.”',points:[[6,15],[6,11],[4,11],[4,7],[8,7],[8,4],[6,4],[6,1]]}];
const mats={ice:new THREE.MeshStandardMaterial({color:0x93c6de,roughness:.24,metalness:.18,flatShading:true}),iceDark:new THREE.MeshStandardMaterial({color:0x426f8b,roughness:.35,metalness:.2,flatShading:true}),snow:new THREE.MeshStandardMaterial({color:0xe2f3f7,roughness:.9,flatShading:true}),floor:new THREE.MeshStandardMaterial({color:0x9cc4d4,roughness:.3,metalness:.23}),metal:new THREE.MeshStandardMaterial({color:0x77868a,roughness:.46,metalness:.65}),orange:new THREE.MeshStandardMaterial({color:0xdd935d,roughness:.6}),dark:new THREE.MeshStandardMaterial({color:0x19374c,roughness:.4}),cyan:new THREE.MeshStandardMaterial({color:0xa1faff,emissive:0x51e3f0,emissiveIntensity:1.5}),warm:new THREE.MeshStandardMaterial({color:0xffd8a3,emissive:0xffad54,emissiveIntensity:2}),red:new THREE.MeshStandardMaterial({color:0xb65845,roughness:.8}),white:new THREE.MeshStandardMaterial({color:0xf0f6f3,roughness:.8})};
function mesh(geo,mat,x=0,y=0,z=0,parent=world){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);parent.add(m);return m}
const box=(w,h,d,mat,x,y,z,parent)=>mesh(new THREE.BoxGeometry(w,h,d),mat,x,y,z,parent);
const sphere=(r,mat,x,y,z,parent,sx=1,sy=1,sz=1)=>{const m=mesh(new THREE.SphereGeometry(r,12,10),mat,x,y,z,parent);m.scale.set(sx,sy,sz);return m};
function rod(a,b,r,mat,parent=world){const av=new THREE.Vector3(...a),bv=new THREE.Vector3(...b),d=bv.clone().sub(av);const m=mesh(new THREE.CylinderGeometry(r,r,d.length(),7),mat,...av.clone().add(bv).multiplyScalar(.5).toArray(),parent);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return m}
function clearWorld(){scene.remove(world);world.traverse(o=>{if(o.geometry)o.geometry.dispose()});world=new THREE.Group();scene.add(world);entities=[];penguins=[];frozen=null;camp=null}
function rng(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}}
function crystal(x,y,z,size=1,material=mats.ice){const m=mesh(new THREE.ConeGeometry(.5*size,3*size,5),material,x,y,z);m.rotation.set(.12*Math.sin(x),x,.12*Math.cos(z));return m}
function penguin(x,z,scale=1,ice=true){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);world.add(g);const body=ice?mats.iceDark:mats.dark,belly=ice?mats.ice:mats.snow;
box(1.25,.22,1.1,mats.ice,x,.1,z);
sphere(.62,body,0,.92,0,g,1,1.4,.86);sphere(.43,belly,0,.87,.31,g,1,1.45,.4);sphere(.44,body,0,1.75,0,g,1,1,.95);
for(const side of [-1,1]){const wing=sphere(.18,body,side*.56,1.01,0,g,.6,2.7,1);wing.rotation.z=side*-.22;g.userData['wing'+side]=wing;sphere(.078,mats.dark,side*.18,1.83,.367,g);sphere(.035,ice?mats.cyan:mats.white,side*.18,1.846,.427,g);sphere(.17,mats.orange,side*.23,.23,.23,g,1,.4,1.6)}
const beak=mesh(new THREE.ConeGeometry(.14,.34,4),ice?mats.ice:mats.orange,0,1.65,.52,g);beak.rotation.x=Math.PI/2;
if(ice){box(.6,.06,.45,mats.snow,0,2.11,-.04,g);crystal(x+.62,.5,z-.32,.28)}return g}
function bear(x,z){const g=new THREE.Group();world.add(g);g.position.set(x,0,z);sphere(.85,mats.white,0,1.3,0,g,1,1.15,.75);sphere(.68,mats.white,0,2.35,0,g,1,.95,.85);sphere(.32,mats.white,0,2.23,.54,g,1,.67,.85);sphere(.13,mats.dark,0,2.31,.79,g);for(const s of [-1,1]){sphere(.2,mats.white,s*.46,2.85,0,g);sphere(.055,mats.dark,s*.23,2.5,.51,g);sphere(.32,mats.white,s*.43,.4,0,g,1,1.4,1);const arm=sphere(.28,mats.white,s*.87,1.42,.07,g,.8,1.65,1);g.userData['arm'+s]=arm}return g}
function human(x,z){const g=new THREE.Group();world.add(g);g.position.set(x,0,z);box(.68,.85,.43,mats.orange,0,1.06,0,g);sphere(.32,mats.snow,0,1.78,0,g);sphere(.23,new THREE.MeshStandardMaterial({color:0xd7b3a3}),0,1.79,.17,g);box(.5,.11,.15,mats.dark,0,1.84,.35,g);box(.64,.2,.48,mats.orange,0,1.53,0,g);for(const s of [-1,1]){box(.22,.68,.25,mats.dark,s*.22,.4,0,g);const arm=box(.2,.73,.25,mats.orange,s*.48,1.05,0,g);arm.rotation.z=s*.12;g.userData['arm'+s]=arm}box(.57,.6,.3,mats.red,0,1.14,-.35,g);return g}
function ladder(x,z,decor=false){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);const h=decor?3.7:5.8;for(const s of [-1,1])rod([s*.58,.1,0],[s*.58,h,-.45],.065,mats.metal,g);for(let y=.3;y<h;y+=.42)rod([-.62,y,-y/h*.45],[.62,y,-y/h*.45],.045,mats.metal,g);if(decor){g.rotation.z=.28;g.rotation.y=.6}else{box(1.8,.12,1.6,mats.ice,0,h,-.6,g);const light=new THREE.PointLight(0x91ffff,20,14,1.8);light.position.set(x,3,z);world.add(light);const ring=mesh(new THREE.TorusGeometry(1.05,.055,6,32),mats.cyan,x,2,z+.1);ring.scale.y=1.6;}return g}
function igloo(x,z){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);for(let row=0;row<4;row++){const r=2.15*Math.sqrt(1-Math.pow(row/4,2));const count=Math.max(6,14-row*2);for(let j=0;j<count;j++){const a=j/count*Math.PI*2+(row%2)*.2;if(row<2&&Math.sin(a)>.85)continue;const m=box(.88,.53,.5,mats.snow,Math.cos(a)*r,row*.49+.28,Math.sin(a)*r,g);m.rotation.y=-a;}}sphere(.82,mats.snow,0,1.89,0,g,1,.25,1);box(.13,1.3,1.1,mats.snow,-.64,.65,1.9,g);box(.13,1.3,1.1,mats.snow,.64,.65,1.9,g);box(1.4,.25,1.1,mats.snow,0,1.32,1.9,g);sphere(.2,mats.warm,0,.5,1.35,g);const light=new THREE.PointLight(0xffc180,9,9);light.position.set(x,.8,z+1.5);world.add(light);return g}
function supplies(x,z){box(.7,.55,.55,mats.red,x,.28,z);box(.76,.06,.61,mats.metal,x,.58,z);rod([x+.7,.12,z],[x+1.1,1.35,z-.3],.035,mats.metal);box(.36,.06,.12,mats.metal,x+1.1,1.37,z-.3);const rope=mesh(new THREE.TorusGeometry(.35,.06,6,20),mats.orange,x-.6,.08,z);rope.rotation.x=Math.PI/2}
function snowParticles(count=400,spread=70){const a=new Float32Array(count*3);const random=rng(988);for(let i=0;i<a.length;i+=3){a[i]=(random()-.5)*spread;a[i+1]=random()*12;a[i+2]=(random()-.5)*spread}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(a,3));const m=new THREE.Points(geo,new THREE.PointsMaterial({color:0xecfaff,size:.035,transparent:true,opacity:.7}));world.add(m);entities.push({kind:'snow',obj:m})}
function menuWorld(){clearWorld();scene.background=new THREE.Color(0x1e3d50);scene.fog=new THREE.FogExp2(0x325469,.032);hemi.intensity=2;sun.intensity=2.3;box(70,.4,90,mats.floor,0,-.25,-22);const random=rng(32);for(let i=0;i<19;i++){const z=9-i*4.1;for(const s of [-1,1]){box(3+random()*2,11+random()*4,4.4,i%3?mats.ice:mats.iceDark,s*(7+random()),5,z);crystal(s*(5.8+random()),9,z,2+random(),mats.ice);crystal(s*(5.6+random()*2),1,z,1.1+random());}if(i%3===0)box(17,.8,2,mats.ice,0,11,z)}
for(let i=0;i<12;i++){const m=box(.03,.012,9,mats.iceDark,-3+i*.6,.015,-1-i*.4);m.rotation.y=.4}const p=penguin(2.3,-4,1.55);p.rotation.y=-.2;entities.push({kind:'statue',obj:p});ladder(-5,-14,true);supplies(-4,-8);box(2.5,.45,2.4,mats.snow,2.3,-.15,-4);snowParticles();camera.position.set(-2.7,2.5,9);camera.lookAt(.3,1.8,-10);fill.position.set(3,3,-2);}
function carve(points){grid=Array.from({length:HEIGHT},()=>Array(WIDTH).fill(1));route=[];let [x,z]=points[0];grid[z][x]=0;route.push([x,z]);for(const [tx,tz]of points.slice(1)){while(x!==tx||z!==tz){if(x!==tx)x+=Math.sign(tx-x);else z+=Math.sign(tz-z);grid[z][x]=0;route.push([x,z]);}}const random=rng(321+level*231);for(let i=3;i<route.length-3;i+=4){let [bx,bz]=route[i];let [dx,dz]=random()>.5?[1,0]:[-1,0];for(let n=0;n<2+Math.floor(random()*3);n++){bx+=dx;bz+=dz;if(bx<1||bx>=WIDTH-1||bz<1||bz>=HEIGHT-1)break;if(grid[bz][bx]===0)break;grid[bz][bx]=0;}}}
const pos=([x,z])=>new THREE.Vector3((x-6)*CELL,0,(z-8)*CELL);
const cellAt=(x,z)=>[Math.round(x/CELL)+6,Math.round(z/CELL)+8];
function wallAt(x,z){const [gx,gz]=cellAt(x,z);return !grid[gz]||grid[gz][gx]!==0}
function canMove(x,z){const r=.28;return !wallAt(x-r,z-r)&&!wallAt(x+r,z-r)&&!wallAt(x-r,z+r)&&!wallAt(x+r,z+r)}
function lineOfSight(a,b){const d=a.distanceTo(b);for(let s=.4;s<d-.3;s+=.35){const p=a.clone().lerp(b,s/d);if(wallAt(p.x,p.z))return false}return true}
function buildLevel(n){level=n;clearWorld();const st=stages[n];scene.background=new THREE.Color(st.color);scene.fog=new THREE.FogExp2(st.color,st.fog);hemi.intensity=1.65+n*.28;sun.intensity=1.8+n*.45;carve(st.points);const campCell=[Math.min(WIDTH-2,route[Math.floor(route.length*.66)][0]+1),route[Math.floor(route.length*.66)][1]];for(let dz=-1;dz<=1;dz++)if(grid[campCell[1]+dz])grid[campCell[1]+dz][campCell[0]]=0;gaps=new Set();if(n>=2){let wanted=n===2?3:2;for(let i=3;i<route.length-4&&wanted;i+=3){const p=route[i],prev=route[i-1],next=route[i+1];if(p[0]===prev[0]&&p[0]===next[0]){gaps.add(p.join(','));wanted--;}}}
const random=rng(127+n);for(let z=0;z<HEIGHT;z++)for(let x=0;x<WIDTH;x++){const px=(x-6)*CELL,pz=(z-8)*CELL;if(grid[z][x]){const h=n===4?1.3+random()*1.7:n===3?3+random()*2.5:5.8+random()*2.5;const m=box(CELL+.03,h,CELL+.03,(x+z)%5?mats.ice:mats.iceDark,px,h/2-.2,pz);if(n>=3)box(CELL+.08,.16,CELL+.08,mats.snow,px,h-.16,pz);if(random()>.5&&n<4){const c=crystal(px+(random()-.5)*3,h+.1,pz,1+random());c.rotation.z=.15;}if(n<3&&random()>.75){const c=crystal(px,4,pz,1.5);c.rotation.z=Math.PI;}}else{if(gaps.has(x+','+z)){box(CELL,.4,1.25,mats.floor,px,-.24,pz-1.38);box(CELL,.4,1.25,mats.floor,px,-.24,pz+1.38);box(CELL,.2,1.5,mats.iceDark,px,-7,pz);for(const s of[-1,1])box(.8,.14,.5,mats.snow,px+s*.8,.05,pz-1.35);}else box(CELL,.4,CELL,mats.floor,px,-.24,pz);if(random()>.65&&!gaps.has(x+','+z)){const c=crystal(px+1.65,.35,pz+1.5,.27);c.rotation.z=.3;}}}
if(n<2){box(WIDTH*CELL,.6,HEIGHT*CELL,mats.iceDark,0,8.5,0);for(let i=0;i<8;i++){const p=pos(route[Math.floor(i*route.length/8)]);const c=crystal(p.x,7.3,p.z,1.1);c.rotation.x=Math.PI;}}
for(let i=1;i<route.length-1;i+=2){const p=pos(route[i]);if(gaps.has(route[i].join(',')))continue;const mark=box(.1,.014,.55,mats.cyan,p.x-.8,.003,p.z);const next=pos(route[i+1]);mark.rotation.y=Math.atan2(next.x-p.x,next.z-p.z);}
const pn=n===0?1:n===1?2:3;for(let j=0;j<pn;j++){const idx=Math.floor(route.length*(.26+j*.21));const p=pos(route[idx]);if(gaps.has(route[idx].join(',')))continue;const g=penguin(p.x+1.06,p.z,.9);const toward=pos(route[Math.max(0,idx-2)]).sub(g.position);g.rotation.y=Math.atan2(toward.x,toward.z);penguins.push({obj:g,pos:g.position.clone(),seen:false,attached:false,lost:0,released:false});}
const cp=pos(campCell);camp=cp.clone();igloo(cp.x,cp.z);supplies(cp.x-1.5,cp.z+1.5);
const lp=pos(route[route.length-1]);exitPos.copy(lp);if(n<4)ladder(lp.x,lp.z);else{const ring=mesh(new THREE.TorusGeometry(1.8,.09,8,40),mats.warm,lp.x,2.1,lp.z);ring.scale.y=1.5;const l=new THREE.PointLight(0xffffff,45,25);l.position.set(lp.x,3,lp.z);world.add(l);}
const gear=pos(route[3]);supplies(gear.x-1.3,gear.z-.7);if(n===1||n===3){const p=pos(route[Math.floor(route.length*.42)]);ladder(p.x-1.6,p.z,true);}
if(n>=3){for(let i=0;i<18;i++){const a=i/18*Math.PI*2;const m=mesh(new THREE.ConeGeometry(12+random()*8,25+random()*23,5),mats.snow,Math.cos(a)*57,6,Math.sin(a)*65);m.rotation.y=random()*3;}snowParticles(550,90);}else snowParticles(220,65);
player.copy(pos(route[0]));yaw=0;pitch=0;jumpY=0;jumpV=0;fallTime=0;crumbs=[player.clone().add(new THREE.Vector3(0,0,1.6)),player.clone()];eul.copy(crumbs[0]);keys={};transitioning=false;
$('stageNum').textContent=`DEPTH 0${n+1} / 05`;$('stageName').textContent=st.name;$('altitude').textContent=st.depth;$('objective').textContent=n===4?'마지막 빛의 문까지 에울과 함께 걸어가세요.':n===2?'갈라진 틈은 점프로 건너고, 사다리에서 E를 누르세요.':'푸른 표식을 따라 사다리를 찾고 E로 올라가세요.';
checkpoint=n;save('frozen-progress',n);updateFollowHUD();camera.position.copy(player);camera.position.y=eye;camera.rotation.set(0,0,0);}
function showScreen(id){for(const s of ['menu','story','hud','pause','gameover','ending'])$(s).hidden=s!==id;document.body.classList.toggle('playing',id==='hud');$('warning').hidden=true;}
const stories=[['균열 아래로','김올페와 박에울은 남극의 눈밭에서 놀고 있었습니다.\n발밑에서 작은 소리가 났습니다.\n\n에울은 크레바스 아래로 떨어졌습니다.\n아래로, 더 아래로. 끝이 없는 흰 어둠 속으로.'],['아무 지도에도 없는 곳','김올페는 밧줄을 타고 내려갔습니다.\n그 끝에는 하늘도, 출구도 없는 얼음 복도가 있었습니다.\n\n누군가 버린 등반 장비. 발자국 없는 이글루.\n그리고 얼음 속에 잠든 박에울.'],['남극에 없는 손님','“북극곰이 왜 남극에…?”\n“나도 그게 궁금하군. 우선 잘 들어.”\n\n“그 아이를 깨우고 네가 앞장서. 바깥에 도착하기 전에는\n절대로 뒤돌아 그 아이를 보지 마. 얼음이 데려갈 테니까.”'],['이천사를 조심해','“펭귄 석상의 이름은 이천사야. 마주치면 눈을 맞춘 채 지나가.\n시선을 놓치면 등에 붙을 거야. 조금 무거울 뿐이지.\n이글루에 가면 내려놓을 수 있어.”\n\n“푸른 표식을 따라 다섯 층을 올라가. 둘 다 빛을 밟을 때까지.”\n북극곰은 눈발 속으로 사라졌습니다.'],['내 목소리만 따라와','“에울아, 일어나. 집에 가자.”\n\n박에울이 천천히 눈을 떴습니다.\n김올페는 손을 내밀고, 앞을 향해 섰습니다.\n\n이제 당신이 김올페입니다. 돌아보지 말고, 함께 걸으세요.']];
function displayStory(){const [title,txt]=stories[storyPage];$('storyIndex').textContent=`PROLOGUE / 0${storyPage+1}`;$('storyTitle').textContent=title;$('storyText').textContent=txt;$('nextStory').innerHTML=storyPage===4?'에울과 함께 출발 <span>→</span>':'계속 <span>→</span>';}
function startStory(){initAudio();elapsed=0;storyPage=0;mode='story';showScreen('story');displayStory();}
function enterLevel(n){buildLevel(n);mode='playing';showScreen('hud');say(stages[n].note,6);lock();}
function lock(){if(matchMedia('(pointer:coarse)').matches)return;try{const p=canvas.requestPointerLock();if(p&&p.catch)p.catch(()=>{dragMode=true;$('capture').hidden=true;say('마우스를 누른 채 드래그하거나 ← →로 시선을 조절하세요.',7)})}catch{dragMode=true;$('capture').hidden=true}}
function unlock(){if(document.pointerLockElement)document.exitPointerLock()}
function pauseGame(){if(mode!=='playing')return;mode='paused';keys={};showScreen('pause');unlock();}
function resume(){mode='playing';showScreen('hud');lock()}
function menu(){mode='menu';unlock();menuWorld();showScreen('menu');$('continueBtn').hidden=checkpoint===null;}
function say(txt,duration=4){$('subtitle').textContent=txt;subtitleUntil=worldTime+duration;}
function updateFollowHUD(){const count=penguins.filter(p=>p.attached).length;$('penguinState').textContent=`펭귄 ${count} · ${count?'속도 '+Math.round(100/(1+count*.23))+'%':'정상 속도'}`;}
function callEul(){if(mode!=='playing'||worldTime-lastCall<3)return;lastCall=worldTime;const lines=['박에울: “응, 여기 있어. 앞만 봐.”','박에울: “조금 춥지만… 네 발소리가 들려.”','박에울: “보고 싶어도 참아. 나도 그러고 있으니까.”','박에울: “펭귄이 네 등에 붙어 있어. 귀엽긴 하다.”'];say(lines[Math.floor(Math.random()*(penguins.some(p=>p.attached)?4:3))]);tone(480,.1,.07);}
function interact(){if(mode!=='playing')return;if(player.distanceTo(exitPos)<3.3){if(level===4){win();return}tone(660,.25,.14);enterLevel(level+1);return}if(camp&&player.distanceTo(camp)<4.3){let count=0;for(const p of penguins)if(p.attached){p.attached=false;p.released=true;count++;}updateFollowHUD();say(count?'이천사들이 이글루에 내려앉았습니다. 발걸음이 가벼워졌어요.':'박에울: “여긴 바람이 안 들어와. 잠깐 쉬었다 가자.”');tone(330,.35,.1)}}
function lose(reason='look'){if(mode!=='playing')return;mode='over';keys={};unlock();showScreen('gameover');$('overTitle').textContent=reason==='look'?'너를 돌아본 순간.':'발밑의 빛이 사라졌다.';$('overText').innerHTML=reason==='look'?'박에울의 마지막 숨이 하얗게 굳었습니다.<br>부르고 싶었던 이름만 얼음 속에 남았습니다.':'얇은 빙하가 발끝에서 멀어졌습니다.<br>다음에는 틈 앞에서 달리며 점프하세요.';if(reason==='look'){frozen=human(eul.x,eul.z);frozen.traverse(o=>{if(o.isMesh)o.material=mats.ice});const c=crystal(eul.x,1.6,eul.z,1.25);c.scale.y=1.2;camera.lookAt(eul.x,1.3,eul.z);}tone(105,1,.3);}
let endingBear,endingEul,endingPenguins=[];
function win(){mode='ending';keys={};unlock();clearWorld();scene.background=new THREE.Color(0xc0e6ed);scene.fog=new THREE.FogExp2(0xd2eef3,.01);hemi.intensity=3;sun.intensity=3;box(110,.6,110,mats.snow,0,-.35,0);for(let i=0;i<13;i++){const a=i*Math.PI*2/13;mesh(new THREE.ConeGeometry(10,18+(i%3)*9,5),mats.ice,Math.cos(a)*50,2,Math.sin(a)*50)}endingBear=bear(3,-2);endingEul=human(.6,-.2);endingPenguins=[penguin(4.6,1,1,false),penguin(1.9,1.8,.75,false),penguin(5.5,-2,.8,false)];camera.position.set(-4,2.8,10);camera.lookAt(1.4,1.4,0);snowParticles(300,50);showScreen('ending');$('endingStats').textContent=`함께 오른 층 5 / 5 · ${Math.floor(elapsed/60)}분 ${Math.floor(elapsed%60)}초의 약속`;checkpoint=null;save('frozen-progress',null);[523,659,784,1047].forEach((v,i)=>setTimeout(()=>tone(v,.7,.11),i*190));}
let audioCtx=null,master=null,wind=null;
function initAudio(){if(audioCtx){audioCtx.resume();return}try{audioCtx=new(window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=settings.volume;master.connect(audioCtx.destination);const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+Math.random()*.04-.02)/1.015;data[i]=last*2}const src=audioCtx.createBufferSource();src.buffer=buffer;src.loop=true;const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=450;wind=audioCtx.createGain();wind.gain.value=.18;src.connect(filter);filter.connect(wind);wind.connect(master);src.start()}catch{}}
function tone(freq,duration,volume=.1){if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(master);o.start();o.stop(audioCtx.currentTime+duration);}
function syncSettings(){for(const k of ['brightness','sensitivity','volume','fov']){$(k).value=settings[k];$(k+'Out').textContent=k==='fov'?settings[k]+'°':Math.round(settings[k]*100)+'%';}$('bob').checked=settings.bob;renderer.toneMappingExposure=settings.brightness;camera.fov=settings.fov;camera.updateProjectionMatrix();if(master)master.gain.value=settings.volume;save('frozen-settings',settings)}
function openSettings(){screenBeforeDialog=mode;if(mode==='playing')pauseGame();syncSettings();$('settingsDialog').showModal()}
for(const k of ['brightness','sensitivity','volume','fov'])$(k).addEventListener('input',()=>{settings[k]=+$(k).value;syncSettings()});$('bob').onchange=()=>{settings.bob=$('bob').checked;syncSettings()};$('resetSettings').onclick=()=>{settings={...defaults};syncSettings()};
$('start').onclick=startStory;$('again').onclick=()=>{menuWorld();startStory()};$('nextStory').onclick=()=>{if(++storyPage>=stories.length)enterLevel(0);else displayStory()};$('skipStory').onclick=()=>enterLevel(0);$('continueBtn').onclick=()=>{initAudio();enterLevel(checkpoint??0)};$('helpBtn').onclick=()=>$('helpDialog').showModal();$('settingsBtn').onclick=openSettings;$('pauseSettings').onclick=openSettings;document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('pauseBtn').onclick=pauseGame;$('resume').onclick=resume;$('restartStage').onclick=()=>enterLevel(level);$('retry').onclick=()=>enterLevel(level);$('toMenu').onclick=menu;$('overMenu').onclick=menu;$('capture').onclick=lock;$('touchUse').onclick=interact;$('touchCall').onclick=callEul;
document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===canvas)$('capture').hidden=true;else if(mode==='playing')pauseGame()});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.code==='Escape'){if(mode==='playing')pauseGame();else if(mode==='paused')resume();return}if(mode!=='playing')return;if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyW','KeyA','KeyS','KeyD'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='KeyQ')callEul();if(e.code==='Space'&&jumpY===0){jumpV=6;tone(170,.12,.025)}});
document.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};pauseGame()});document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseGame()});
document.addEventListener('mousemove',e=>{if(mode==='playing'&&document.pointerLockElement===canvas){yaw-=e.movementX*.002*settings.sensitivity;pitch=Math.max(-1.05,Math.min(1.05,pitch-e.movementY*.002*settings.sensitivity));}});
canvas.addEventListener('pointerdown',e=>{if(mode!=='playing')return;if(e.pointerType==='touch'||dragMode){touchLook={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)}else lock()});canvas.addEventListener('pointermove',e=>{if(mode==='playing'&&touchLook&&e.pointerId===touchLook.id){yaw-=(e.clientX-touchLook.x)*.005*settings.sensitivity;pitch=Math.max(-1,Math.min(1,pitch-(e.clientY-touchLook.y)*.005*settings.sensitivity));touchLook.x=e.clientX;touchLook.y=e.clientY}});canvas.addEventListener('pointerup',()=>touchLook=null);canvas.addEventListener('pointercancel',()=>touchLook=null);
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();const k=b.dataset.key;keys[k]=true;b.setPointerCapture(e.pointerId);if(k==='Space'&&jumpY===0&&mode==='playing')jumpV=6};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false;});
function updateFollower(){if(crumbs[crumbs.length-1].distanceTo(player)>.18)crumbs.push(player.clone());let remaining=3.2;eul.copy(crumbs[0]);for(let i=crumbs.length-1;i>0;i--){const d=crumbs[i].distanceTo(crumbs[i-1]);if(remaining<=d){eul.copy(crumbs[i]).lerp(crumbs[i-1],remaining/d);if(i>2)crumbs.splice(0,i-2);break}remaining-=d;}}
function updateGame(dt){elapsed+=dt;const left=keys.ArrowLeft?1:0,right=keys.ArrowRight?1:0;yaw+=(left-right)*dt*1.7;const count=penguins.filter(p=>p.attached).length;const groundSpeed=(keys.ShiftLeft||keys.ShiftRight?5.8:4.1)/(1+count*.23);const speed=jumpY>0||jumpV>0?Math.max(4.1,groundSpeed):groundSpeed;let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),strafe=(keys.KeyD?1:0)-(keys.KeyA?1:0);const len=Math.hypot(forward,strafe)||1;forward/=len;strafe/=len;const dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*strafe)*dt*speed,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*strafe)*dt*speed;const old=player.clone();if(canMove(player.x+dx,player.z))player.x+=dx;if(canMove(player.x,player.z+dz))player.z+=dz;const moving=old.distanceTo(player)>.001;if(moving){walkPhase+=dt*speed*2.4;steps++;if(worldTime-lastFoot>.46*4.1/speed&&jumpY===0){lastFoot=worldTime;tone(95+Math.random()*30,.06,.035)}}
if(jumpV!==0||jumpY>0){jumpV-=13*dt;jumpY+=jumpV*dt;if(jumpY<=0){jumpY=0;jumpV=0;}}
const [cx,cz]=cellAt(player.x,player.z);const czWorld=(cz-8)*CELL;const overGap=gaps.has(cx+','+cz)&&Math.abs(player.z-czWorld)<.76;if(overGap&&jumpY<.08){fallTime+=dt;camera.position.y-=dt*8;if(fallTime>.22){lose('fall');return}}else fallTime=0;
updateFollower();const view=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));const toEul=eul.clone().sub(player);const dist=toEul.length();const alignment=view.dot(toEul.normalize());const eulVisible=dist<6&&lineOfSight(player,eul);$('warning').hidden=!(alignment>.12&&eulVisible);if(alignment>.72&&eulVisible){lose();return}
for(const p of penguins){if(p.attached||p.released)continue;const offset=p.pos.clone().sub(player),d=offset.length();const gaze=new THREE.Vector3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));const target=offset.clone();target.y=1.1-eye-jumpY;const visible=d<13&&gaze.dot(target.normalize())>Math.cos(settings.fov*Math.PI/360)&&lineOfSight(player,p.pos);if(visible&&!p.seen){p.seen=true;say('이천사와 눈이 마주쳤습니다. 바라본 채 옆걸음으로 지나가세요.',4);tone(840,.13,.06)}if(p.seen){if(visible)p.lost=0;else p.lost+=dt;if(p.lost>.45){p.attached=true;p.obj.visible=false;updateFollowHUD();say('톡. 이천사가 등에 붙었습니다. 이글루에서 내려놓을 수 있어요.',4);tone(240,.15,.12);}}}
camera.position.set(player.x,eye+jumpY+(settings.bob&&moving?Math.sin(walkPhase)*.045:0)-fallTime*5,player.z);camera.rotation.set(pitch,yaw,0);fill.position.set(player.x,2.7,player.z-1);$('compass').textContent=`${['N','W','S','E'][((Math.round(yaw/(Math.PI/2))%4)+4)%4]} · ${((Math.round(-yaw*180/Math.PI)%360)+360)%360}°`;
$('interaction').textContent=player.distanceTo(exitPos)<3.3?level===4?'E · 에울과 함께 빛 속으로':'E · 다음 층으로 올라가기':camp&&player.distanceTo(camp)<4.3?'E · 이글루에서 쉬기':'';
if(level===4&&player.distanceTo(exitPos)<1.25)win();}
let prev=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-prev)/1000,.045);prev=now;worldTime+=dt;if(mode==='playing')updateGame(dt);else if(mode==='menu'||mode==='story'){camera.position.x=-2.7+Math.sin(worldTime*.13)*.25;camera.lookAt(.3,1.8,-10)}else if(mode==='ending'){for(const g of [endingBear,endingEul])for(const s of[-1,1]){const arm=g?.userData['arm'+s];if(arm)arm.rotation.z=s*(.7+Math.sin(worldTime*9)*.35);}for(const g of endingPenguins)for(const s of[-1,1])g.userData['wing'+s].rotation.z=s*(.7+Math.sin(worldTime*9)*.5);}
for(const e of entities)if(e.kind==='snow'){e.obj.position.y=-worldTime*.15%5;e.obj.rotation.y=Math.sin(worldTime*.05)*.04;}if(worldTime>subtitleUntil)$('subtitle').textContent='';if(wind)wind.gain.setTargetAtTime(mode==='playing'?.18:.06,audioCtx.currentTime,.4);renderer.render(scene,camera)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
syncSettings();menu();requestAnimationFrame(frame);
